insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('05c37b33-9b4d-4611-8330-e111a5c04353', '938ef4f5-eca1-4dae-8041-bbe5bbde4b1f', $$inleiding: Britt heeft de tetralogie van Fallot$$,
   $$biologie-havo-2025-ii-de-tetralogie-van-fallot-context1.png$$,
   $$Britt is zestien jaar en heeft de tetralogie van Fallot, een aangeboren hartafwijking. Door deze afwijking is ze sneller moe dan haar leeftijdsgenoten. Ze heeft al twee hartoperaties gehad.$$, 'inline'),
  ('0a2cff04-9ea2-4246-a632-1361d6bc3f06', '938ef4f5-eca1-4dae-8041-bbe5bbde4b1f', $$kader: kenmerken van de tetralogie van Fallot (afbeelding 1)$$,
   $$biologie-havo-2025-ii-de-tetralogie-van-fallot-context2.png$$,
   $$De hartafwijking van Britt is al vroeg tijdens de embryonale ontwikkeling ontstaan. Bij de tetralogie van Fallot is de doorgang naar de aorta wijd, en de doorgang naar de longslagader nauw. Ook is er een opening tussen de linkerkamer en de rechterkamer. Zie afbeelding 1.
afbeelding 1: tekening van een hart met de tetralogie van Fallot; de wand van de rechterkamer is zwart en duidelijk verdikt$$, 'inline'),
  ('a68cb578-30e3-4611-a3aa-1e3a921c156c', '938ef4f5-eca1-4dae-8041-bbe5bbde4b1f', $$drie verschillen in de tekst, een vierde in afbeelding 1$$,
   $$biologie-havo-2025-ii-de-tetralogie-van-fallot-context3.png$$,
   $$In de tekst worden drie verschillen genoemd ten opzichte van een normaal gebouwd hart. In afbeelding 1 is een vierde verschil zichtbaar.$$, 'inline'),
  ('a16fe3b2-782e-4bc6-8593-ef9bad6f51af', '938ef4f5-eca1-4dae-8041-bbe5bbde4b1f', $$kader: operatie met een patch in de longslagader (afbeelding 2)$$,
   $$biologie-havo-2025-ii-de-tetralogie-van-fallot-context4.png$$,
   $$Toen Britt zes maanden oud was, heeft ze een operatie gehad. Bij deze operatie is de doorgang naar de longslagader wijder gemaakt. De hartchirurg heeft toen de wand van de longslagader opengesneden en opgevuld met een stukje kunststof weefsel (een ‘patch’, afbeelding 2). Het nadeel van zo’n operatie is dat de longslagaderklep niet meer volledig sluit, waardoor bloed kan terugstromen naar het hart.
afbeelding 2: tekening van het hart met de longslagader en de patch aangegeven$$, 'inline'),
  ('8f5407ad-c293-4d7a-9a4b-f2ae1dd4935d', '938ef4f5-eca1-4dae-8041-bbe5bbde4b1f', $$vermoeidheid door menging van bloed$$,
   $$biologie-havo-2025-ii-de-tetralogie-van-fallot-context5.png$$,
   $$Als Britt zich inspande, was ze veel eerder moe dan haar leeftijdsgenoten. De slecht sluitende klep was een van de oorzaken. De vermoeidheid werd ook veroorzaakt door de opening tussen haar linker- en rechterkamer. Via deze opening was er menging van bloed uit de linker- en rechterharthelft. Door deze menging werd in de cellen van Britt bij inspanning minder energie geproduceerd dan in die van haar leeftijdsgenoten.$$, 'inline'),
  ('4bb3d413-0e67-4141-aa1c-01537a910351', '938ef4f5-eca1-4dae-8041-bbe5bbde4b1f', $$tweede hartoperatie en de hart-longmachine$$,
   $$biologie-havo-2025-ii-de-tetralogie-van-fallot-context6.png$$,
   $$Onlangs heeft Britt haar tweede hartoperatie gehad. De hartchirurg verving haar slecht sluitende klep door een longslagaderklep van een orgaandonor. Britt is nu minder snel moe. Tijdens de operatie werd haar hart gekoeld, zodat het nauwelijks meer samentrok. Britt lag daarom aan de hart-longmachine. Een hart-longmachine neemt de functie van het hart en de longen tijdelijk over.$$, 'inline'),
  ('9f49deca-87a1-42aa-8446-ea48011e31be', 'a08912df-394c-4ed8-aa35-f81452c67a9e', $$inleiding: kippen met fibromelanose$$,
   $$biologie-havo-2025-ii-zwarte-kip-context1.png$$,
   $$Freek fokt kippen. Op een tentoonstelling ziet hij kippen met zwarte veren. Ook hun botten en spieren zijn zwart. Dit heet fibromelanose en komt onder andere voor bij de kippenrassen ayam cemani uit Indonesië (afbeelding 1) en svarthöna uit Zweden (afbeelding 2).$$, 'inline'),
  ('053cf162-95bd-4c69-9001-203efb4872f9', 'a08912df-394c-4ed8-aa35-f81452c67a9e', $$afbeelding 1 en 2: ayam cemani en svarthöna$$,
   $$biologie-havo-2025-ii-zwarte-kip-context2.png$$,
   $$afbeelding 1: foto van een ayam cemani (zwarte haan)
afbeelding 2: foto van een svarthöna (zwarte kip)$$, 'inline'),
  ('7fb0d47d-c8b2-444e-80e9-6e5f0588fbff', 'a08912df-394c-4ed8-aa35-f81452c67a9e', $$kader: melanine, melanocyten en het EDN3-gen$$,
   $$biologie-havo-2025-ii-zwarte-kip-context3.png$$,
   $$Een zwarte kleur van kippenveren wordt veroorzaakt door het eiwit melanine. Melanine wordt geproduceerd door pigmentcellen: de melanocyten. Tijdens de embryonale ontwikkeling komen de melanocyten terecht op specifieke plekken in de huid, en geven zo de veren hun kleur. Kippen met fibromelanose hebben een mutatie in het autosomale EDN3- gen. Door deze mutatie komen de melanocyten in het gehele lichaam terecht, waardoor deze kippen volledig zwart zijn.$$, 'inline'),
  ('dbe22787-ab13-45df-bc79-c64e2c3eabb2', 'a08912df-394c-4ed8-aa35-f81452c67a9e', $$drie uitspraken over de kleuring$$,
   $$biologie-havo-2025-ii-zwarte-kip-context4.png$$,
   $$Hieronder staan uitspraken over de kleuring van de twee zwarte kippenrassen.
1 Het EDN3-gen codeert voor melanine.
2 Het EDN3-gen bevindt zich in alle cellen met een kern.
3 De mutatie aan het EDN3-gen ontstaat tijdens de embryonale ontwikkeling.$$, 'inline'),
  ('b4a958e1-4389-4b87-8006-ced724511e56', 'a08912df-394c-4ed8-aa35-f81452c67a9e', $$dezelfde mutatie bij twee rassen$$,
   $$biologie-havo-2025-ii-zwarte-kip-context5.png$$,
   $$Ayam cemani’s en svarthöna’s hebben dezelfde, uiterst complexe, mutatie aan het EDN3-gen. Wetenschappers denken daarom dat de twee rassen afstammen van een gemeenschappelijke volledig zwart-gekleurde voorouder.$$, 'inline'),
  ('72987135-6ce6-4bbb-b18a-3441bc492a58', 'a08912df-394c-4ed8-aa35-f81452c67a9e', $$kader: stamboom van Freeks kippen (afbeelding 3)$$,
   $$biologie-havo-2025-ii-zwarte-kip-context6.png$$,
   $$Freek wil graag zwarte kippen gaan fokken. Van een bevriende kippenfokker koopt hij een aantal eieren van kippen met fibromelanose. Nadat de eieren zijn uitgekomen, maakt Freek een stamboom van de ouders en de kuikens (afbeelding 3).
afbeelding 3: stamboom: generatie I: hen 1 met fibromelanose × haan 2 met fibromelanose; generatie II: 1 hen met, 2 haan met, 3 lichtbruine hen, 4 haan met, 5 haan met, 6 hen met, 7 hen met, 8 lichtbruine haan, 9 hen met, 10 lichtbruine haan, 11 hen met fibromelanose
Freek kiest haan II-5 om verder mee te fokken. Voor het fokken zou het gunstig zijn als de haan homozygoot is voor de autosomaal overervende eigenschap fibromelanose.$$, 'inline'),
  ('ddfb8729-9d67-42a5-be24-af243025a7f4', 'a08912df-394c-4ed8-aa35-f81452c67a9e', $$kruising van haan II-5 met het lichtbruine hennetje$$,
   $$biologie-havo-2025-ii-zwarte-kip-context7.png$$,
   $$Om uit te sluiten dat haan II-5 heterozygoot is voor de eigenschap fibromelanose, kruist Freek hem met het lichtbruine hennetje.$$, 'inline'),
  ('a7cb334d-9e4c-43f0-8523-e68a16e987cb', 'a08912df-394c-4ed8-aa35-f81452c67a9e', $$inteelt en recessieve erfelijke afwijkingen$$,
   $$biologie-havo-2025-ii-zwarte-kip-context8.png$$,
   $$Fokkers kruisen vaker broers en zussen onderling om bepaalde gewenste eigenschappen te behouden. Dit heet inteelt. Hierbij is de kans echter ook groot dat recessieve erfelijke afwijkingen tot uiting komen.$$, 'inline'),
  ('82f82574-e31c-47ab-82c9-321a6df8d573', '27085b21-a0e0-455f-b7c5-b1e3e040d76a', $$inleiding: CO₂-uitstoot bij productie van bio-ethanol uit suikerbieten$$,
   $$biologie-havo-2025-ii-groene-energie-nog-groener-context1.png$$,
   $$Biobrandstoffen kunnen een duurzaam alternatief zijn voor fossiele brandstoffen. Stefan Hol werkt bij Wageningen Universiteit en Research aan onderzoek naar de CO₂-uitstoot bij de productie van bio-ethanol uit suikerbieten.$$, 'inline'),
  ('7cfa825b-4909-4d33-8859-8543fab413ed', '27085b21-a0e0-455f-b7c5-b1e3e040d76a', $$kader: productie van bio-ethanol uit suikerbietenpulp$$,
   $$biologie-havo-2025-ii-groene-energie-nog-groener-context2.png$$,
   $$Doordat suikerbieten veel sacharose bevatten, zijn ze erg geschikt voor de productie van bio-ethanol (alcohol). De verse suikerbieten worden gewassen en dan vermalen tot pulp. De pulp wordt verhit om micro-organismen te doden. Als de pulp is afgekoeld, wordt deze in een bioreactor gebracht waarin gistcellen aanwezig zijn. De gistcellen gaan dan ethanol produceren.$$, 'inline'),
  ('2d7328c0-63f1-40e6-a9ee-a1f20935b391', '27085b21-a0e0-455f-b7c5-b1e3e040d76a', $$polysachariden en toegevoegde enzymen$$,
   $$biologie-havo-2025-ii-groene-energie-nog-groener-context3.png$$,
   $$Behalve sacharose, bevatten suikerbieten ook veel polysachariden. Daarom worden bepaalde enzymen toegevoegd aan de pulp in de bioreactor. Hierdoor wordt de ethanol-opbrengst hoger.$$, 'inline'),
  ('9da4cc62-694f-4f55-84e6-3c1fb159bf51', '27085b21-a0e0-455f-b7c5-b1e3e040d76a', $$geen zuurstof bij de gistcellen$$,
   $$biologie-havo-2025-ii-groene-energie-nog-groener-context4.png$$,
   $$Voor de productie van ethanol is het belangrijk dat er geen zuurstof aanwezig is bij de gistcellen.$$, 'inline'),
  ('0fb42fbe-d31c-4ff9-9e48-4460273c44c3', '27085b21-a0e0-455f-b7c5-b1e3e040d76a', $$met zuurstof andere eindproducten$$,
   $$biologie-havo-2025-ii-groene-energie-nog-groener-context5.png$$,
   $$Als er wel zuurstof aanwezig zou zijn, zouden andere eindproducten ontstaan in de gistcellen.$$, 'inline'),
  ('940650fd-f57c-4bda-a1d4-89f82632e6f4', '27085b21-a0e0-455f-b7c5-b1e3e040d76a', $$kader: model voor de CO₂-uitstoot per kilogram suikerbiet$$,
   $$biologie-havo-2025-ii-groene-energie-nog-groener-context6.png$$,
   $$Bij teelt, transport, opslag en verwerking van suikerbieten komt koolstofdioxide vrij. Deze CO₂-uitstoot draagt bij aan het versterkte broeikaseffect. Stefan Hol stelde het volgende model op om deze CO₂-uitstoot per kilogram suikerbiet te kunnen berekenen.
Totaal CO₂ = CO₂ teelt + CO₂ transport + CO₂ opslag + CO₂ verwerking$$, 'inline'),
  ('41d0c738-fa7a-4f76-9432-898ef955ce71', '27085b21-a0e0-455f-b7c5-b1e3e040d76a', $$gemiddelde waarden uit 2020$$,
   $$biologie-havo-2025-ii-groene-energie-nog-groener-context7.png$$,
   $$Stefan Hol gebruikte in zijn berekeningen gemiddelde waarden en ging uit van de situatie zoals die in 2020 was. In de toekomst zullen deze waarden waarschijnlijk lager liggen.$$, 'inline'),
  ('10624d20-aefb-4eb4-a7a7-e31f56a4105e', '27085b21-a0e0-455f-b7c5-b1e3e040d76a', $$pulp of sap; tabel met waarden van teelt en verwerking$$,
   $$biologie-havo-2025-ii-groene-energie-nog-groener-context8.png$$,
   $$Het nadeel van het gebruik van verse suikerbieten is dat deze niet het hele jaar beschikbaar zijn. In plaats van suikerbietenpulp kan suikerbietensap worden gebruikt voor de productie van bio-ethanol. In tegenstelling tot pulp, is het sap lang houdbaar. De productie van sap uit suikerbieten kost echter veel meer energie, waardoor deze manier van ethanol-productie minder duurzaam is. Hieronder staan enkele waarden van de teelt en verwerking van suikerbieten.
opbrengst teelt suikerbieten (ongewassen): 94.500 kg per hectare
percentage zand of klei aan de suikerbieten: 10%
biomassa-gehalte van een gewassen suikerbiet: 24%
gehalte sachariden: 0,73 kg per kg biomassa
opbrengst aan bio-ethanol: 0,52 kg per kg sachariden
CO₂-uitstoot bij gebruik pulp: 0,80 g CO₂ per kg bio-ethanol
CO₂-uitstoot bij gebruik sap: 1,31 g CO₂ per kg bio-ethanol$$, 'inline'),
  ('347dc6e4-f030-4c91-b3f8-8fcb099bebed', '27085b21-a0e0-455f-b7c5-b1e3e040d76a', $$verbranding van bio-ethanol en het broeikaseffect$$,
   $$biologie-havo-2025-ii-groene-energie-nog-groener-context9.png$$,
   $$Bij het verbranden van bio-ethanol komt ook koolstofdioxide vrij. Gebruik van bio-ethanol draagt echter veel minder bij aan het versterkte broeikaseffect dan het gebruik van fossiele brandstoffen.$$, 'inline'),
  ('c4010bf7-d994-45f4-a44d-772d80e0840d', 'e9f20e4f-331b-4c13-8289-3ee4af03fa7e', $$inleiding: Jean heeft long covid$$,
   $$biologie-havo-2025-ii-ademtherapie-bij-long-covid-context1.png$$,
   $$Jean heeft maanden nadat hij covid (corona) had nog steeds last van vermoeidheid en kortademigheid. Zijn huisarts vermoedt het post-covidsyndroom (long covid).$$, 'inline'),
  ('a231b6e9-f5c1-4a04-b8bc-4d50397a8759', 'e9f20e4f-331b-4c13-8289-3ee4af03fa7e', $$zelftest en PCR-test$$,
   $$biologie-havo-2025-ii-ademtherapie-bij-long-covid-context2.png$$,
   $$Na de besmetting met het coronavirus had Jean verkoudheidsklachten. Hij deed een zelftest om te zien of er bepaalde antigenen in zijn neusslijmvlies aanwezig waren. Omdat deze test positief was, liet Jean ook een PCR-test doen. Bij de PCR-test wordt onderzocht of in het neusslijmvlies specifieke stukjes RNA van het coronavirus aanwezig zijn. Deze test gaf ook een positieve uitslag.$$, 'inline'),
  ('d9d57a69-e434-4a4b-82bb-f7ff0be7e75f', 'e9f20e4f-331b-4c13-8289-3ee4af03fa7e', $$kader: diffusiesnelheid in de longblaasjes (formule)$$,
   $$biologie-havo-2025-ii-ademtherapie-bij-long-covid-context3.png$$,
   $$Toen Jean covid had, had hij veel last van kortademigheid. Kortademigheid kan ontstaan als de diffusiesnelheid van zuurstof van de lucht in de longblaasjes naar het bloed verandert. De diffusiesnelheid (V) in de longblaasjes kun je bepalen met de onderstaande formule.
V = D × A × (c₁ − c₂) / x
− D: de diffusieconstante
− A: het diffusieoppervlak
− (c₁ − c₂): het verschil in zuurstofconcentratie tussen bloed en lucht
− x: de diffusie-afstand
Als in de longblaasjes meer slijm aanwezig is, verandert de diffusie-afstand. Als er minder longblaasjes zijn, wordt een andere factor uit de formule kleiner.$$, 'inline'),
  ('12f4e98d-8c37-4a9c-b454-6dae9cb031a8', 'e9f20e4f-331b-4c13-8289-3ee4af03fa7e', $$antistoffen tegen het coronavirus$$,
   $$biologie-havo-2025-ii-ademtherapie-bij-long-covid-context4.png$$,
   $$In de eerste maanden na zijn coronabesmetting had Jean maar een kleine kans om weer corona te krijgen. Zijn bloed bevatte namelijk veel antistoffen tegen het coronavirus.$$, 'inline'),
  ('a65e9ceb-08d8-43e6-af8f-65ab16ed14de', 'e9f20e4f-331b-4c13-8289-3ee4af03fa7e', $$afweercellen prikken geïnfecteerde cellen lek$$,
   $$biologie-havo-2025-ii-ademtherapie-bij-long-covid-context5.png$$,
   $$Er zijn ook veel afweercellen aanwezig die cellen kunnen lekprikken die door het coronavirus zijn geïnfecteerd.$$, 'inline'),
  ('8c16cca8-41dc-4156-ac41-4ee1f08f26c9', 'e9f20e4f-331b-4c13-8289-3ee4af03fa7e', $$opnieuw besmet met een gemuteerd coronavirus$$,
   $$biologie-havo-2025-ii-ademtherapie-bij-long-covid-context6.png$$,
   $$Mensen die immuun geworden zijn na een eerste coronabesmetting kunnen soms kort daarna toch weer corona krijgen. Ze zijn dan besmet geraakt met een gemuteerd coronavirus.$$, 'inline'),
  ('bd7c3f01-2db4-4ffc-82b9-69d818922b8c', 'e9f20e4f-331b-4c13-8289-3ee4af03fa7e', $$kader: RIVM-onderzoek met een controlegroep$$,
   $$biologie-havo-2025-ii-ademtherapie-bij-long-covid-context7.png$$,
   $$Een deel van de mensen die een besmetting met het coronavirus hebben gehad, houdt langdurig last van vermoeidheid, kortademigheid en concentratieproblemen. Dit blijkt uit onderzoek van het RIVM (Rijksinstituut voor Volksgezondheid en Milieu). Het RIVM wil weten of deze klachten daadwerkelijk worden veroorzaakt door de besmetting met het coronavirus. Om dit te onderzoeken vulden een groot aantal mensen direct na een positieve coronatest een vragenlijst in. Deze proefpersonen vulden daarna regelmatig de vragenlijst opnieuw in. De vragenlijsten werden ook afgenomen bij een controlegroep.$$, 'inline'),
  ('701b443c-469a-4e21-b8d5-fbd8c7315d4e', 'e9f20e4f-331b-4c13-8289-3ee4af03fa7e', $$kader: ademtherapie bij een logopedist$$,
   $$biologie-havo-2025-ii-ademtherapie-bij-long-covid-context8.png$$,
   $$De huisarts adviseerde Jean om ademtherapie bij een logopedist te gaan doen. Daarbij leerde hij hoe hij efficiënter kan ademen tijdens het spreken. Zo werd Jean zich meer bewust van zijn ademhalingsbewegingen, en heeft hij minder last van kortademigheid.$$, 'inline'),
  ('cf67c280-ac7e-48a4-b15e-81a5dd2db714', 'e9f20e4f-331b-4c13-8289-3ee4af03fa7e', $$oefening: zo ver mogelijk uitademen$$,
   $$biologie-havo-2025-ii-ademtherapie-bij-long-covid-context9.png$$,
   $$Als eerste oefening moest Jean – na een inademing – langzaam zover mogelijk uitademen, alsof hij een kaars probeert uit te blazen.$$, 'inline'),
  ('6d274cec-85ea-44ad-b9a1-1b1052528629', 'e9f20e4f-331b-4c13-8289-3ee4af03fa7e', $$ademcentrum; lengtedoorsnede hersenen met delen P-T$$,
   $$biologie-havo-2025-ii-ademtherapie-bij-long-covid-context10.png$$,
   $$De ademhaling wordt automatisch geregeld door het ademcentrum. De afbeelding hieronder is een lengtedoorsnede van de hersenen en een deel van het ruggenmerg. Hierin zijn verschillende delen met letters aangegeven.
afbeelding: lengtedoorsnede van de hersenen en het begin van het ruggenmerg met van boven naar onder de letters P (bij de grote hersenen), Q, R, S en T (onderaan)$$, 'inline'),
  ('aaece062-5ef7-4951-bb28-a0510dd1d875', 'b906a85a-3bb3-4e72-a3e6-a48dc9b4ea9d', $$inleiding: project Partridge en biodiversiteit$$,
   $$biologie-havo-2025-ii-project-partridge-context1.png$$,
   $$Het project Partridge is een project van vijf Europese landen. In dit project proberen ecologen en landbouwers om met eenvoudige maatregelen de biodiversiteit te laten toenemen. De patrijs kan hiervan profiteren.$$, 'inline'),
  ('ed7087e7-dfb2-4f18-b12e-d99bec9ccb33', 'b906a85a-3bb3-4e72-a3e6-a48dc9b4ea9d', $$kaders: achteruitgang van de patrijs (afbeelding 1) en voedselweb (afbeelding 2)$$,
   $$biologie-havo-2025-ii-project-partridge-context2.png$$,
   $$In de jaren zeventig van de vorige eeuw kwam de patrijs (Perdix perdix, afbeelding 1) in heel Nederland voor op akkers en graslanden. Door de intensivering van de landbouw nam het aantal geschikte broedplaatsen snel af, waardoor het aantal patrijzen met 95% gedaald is.
afbeelding 1: foto van een patrijs
Het broedsucces van de patrijs hangt vooral af van de beschutting en de hoeveelheid insecten in de directe omgeving van het nest. Patrijs-kuikens eten alleen maar insecten. Volwassen patrijzen voeden zich vooral met plantaardig materiaal, zoals zaden en groene plantendelen van diverse kruiden die op akkers groeien. Af en toe eten ze een insect. Zie het voedselweb in afbeelding 2.
afbeelding 2: voedselweb: vogelmuur → bladluis → loopkever → patrijs-kuiken en volwassen patrijs; vogelmuur, gras en koolzaad → bladhaantje → patrijs-kuiken; vogelmuur, gras en koolzaad → volwassen patrijs; patrijs-kuiken en volwassen patrijs → vos en buizerd$$, 'inline'),
  ('b3c95bf6-96f1-423c-8e39-584b9532c086', 'b906a85a-3bb3-4e72-a3e6-a48dc9b4ea9d', $$tabel: voedingswaarde van insecten, vogelmuur en koolzaad$$,
   $$biologie-havo-2025-ii-project-partridge-context3.png$$,
   $$In de onderstaande tabel is te zien dat de voedingswaarde van insecten verschilt van de voedingswaarde van plantaardig voedsel zoals vogelmuur of zaden van koolzaad.
voedingswaarde per 100 gram eetbaar gedeelte: energie (kJ) / koolhydraten (g) / vetten (g) / eiwitten (g)
insecten: 840 / 2,0 / 4,3 / 38,0
vogelmuur (hele plant): 132 / 4,0 / 0,2 / 3,3
koolzaad (zaad): 2048 / 8,1 / 45,0 / 14,5$$, 'inline'),
  ('898a10fc-651a-4443-823b-f1d42bf19501', 'b906a85a-3bb3-4e72-a3e6-a48dc9b4ea9d', $$kader: keverbank en braakliggende grond (afbeelding 3)$$,
   $$biologie-havo-2025-ii-project-partridge-context4.png$$,
   $$In het project Partridge onderzoeken ecologen of de biodiversiteit op akkers vergroot kan worden door het aanleggen van keverbanken. Een keverbank is een strook grond van 50 tot 70 centimeter hoog, met daarop een lage begroeiing van grassen en struikjes. Deze biedt beschutting en voedsel voor de patrijs-kuikens, die in de periode van eind mei tot halverwege juni uit het ei komen. Naast de keverbank ligt een strook grond die onbegroeid (braakliggend) blijft. Zie afbeelding 3.
afbeelding 3: dwarsdoorsnede: akker, keverbank van 3 m breed en 50-70 cm hoog, braakliggende grond van 3 m, akker$$, 'inline'),
  ('23f29f41-5203-4703-9ed8-6423106c9d9e', 'b906a85a-3bb3-4e72-a3e6-a48dc9b4ea9d', $$stofbaden tegen bloedzuigende mijten$$,
   $$biologie-havo-2025-ii-project-partridge-context5.png$$,
   $$Op de braakliggende grond kunnen patrijzen stofbaden nemen. Zo verwijderen ze bloedzuigende mijten van hun huid.$$, 'inline'),
  ('6122563d-3c58-4be6-b8bb-66a30d3dadb2', 'b906a85a-3bb3-4e72-a3e6-a48dc9b4ea9d', $$hypothese en diagram aantal insecten op keverbank en akker$$,
   $$biologie-havo-2025-ii-project-partridge-context6.png$$,
   $$De hypothese van de ecologen is: een keverbank vergroot de overlevingskans van patrijskuikens. Om dit te testen hebben een aantal akkerbouwers keverbanken aangelegd. De ecologen tellen steeds het aantal insecten op een keverbank en in een controlestrook op een akker zonder keverbank. In het diagram hieronder staan de resultaten van het onderzoek.
diagram: gemiddeld aantal insecten van april tot september; keverbank: ongeveer 220 in april, een piek van ongeveer 350 in juni, een dal van ongeveer 220 in juli en een stijging tot ongeveer 560 in september; akker zonder keverbank: tussen ongeveer 30 en 110, met een piek in mei
Uit het diagram blijkt dat het aantal insecten op de keverbanken groter is dan op akkers zonder keverbank. Hierdoor is de kans op broedsucces van de patrijs er groter. Om hun hypothese te testen, keken de ecologen naar een bepaald gedeelte van het diagram.$$, 'inline'),
  ('18c05b91-dec4-43b4-a3e0-c32d60563b6f', '6c36657f-fe28-464f-a17f-37f3d41de11f', $$inleiding: stikstofuitstoot van een melkveehouderij$$,
   $$biologie-havo-2025-ii-koeientoilet-context1.png$$,
   $$Andrea heeft een melkveehouderij naast natuurgebied het Korenburgerveen. Om de zeldzame planten in het natuurgebied te beschermen, neemt ze maatregelen zodat de uitstoot van stikstof van haar bedrijf vermindert.$$, 'inline'),
  ('208bc5f2-f58c-4698-876a-5ab24c773531', '6c36657f-fe28-464f-a17f-37f3d41de11f', $$kader: urease zet ureum om in ammoniak$$,
   $$biologie-havo-2025-ii-koeientoilet-context2.png$$,
   $$Urine van koeien bevat ureum. In de ontlasting van koeien komen bacteriën voor die het enzym urease produceren. In de stal komen urine en ontlasting met elkaar in contact. Urease zet ureum dan om in ammoniak. Een gedeelte van de ammoniak komt in de lucht en kan zo in de omgeving neerslaan. Dit kan leiden tot eutrofiëring van natuurgebieden.$$, 'inline'),
  ('4d31388f-efc0-4d20-8429-787d3884e485', '6c36657f-fe28-464f-a17f-37f3d41de11f', $$in de wei minder ammoniak dan in de stal$$,
   $$biologie-havo-2025-ii-koeientoilet-context3.png$$,
   $$Als de koeien in de wei lopen, ontstaat er veel minder ammoniak dan wanneer de koeien in de stal staan.$$, 'inline'),
  ('d44d8f52-fde0-4a55-927c-c975333c843f', '6c36657f-fe28-464f-a17f-37f3d41de11f', $$kader: koeientoilet en plasreflex (afbeelding 1)$$,
   $$biologie-havo-2025-ii-koeientoilet-context4.png$$,
   $$Om urine en ontlasting te scheiden, heeft Andrea in de stal twee koeientoiletten geplaatst. Een koeientoilet is een apart hokje in de stal. Als de koe erin loopt, krijgt ze brokjes te eten en sluit het hokje zich. Vervolgens beweegt een opvangbak (afbeelding 1) zich op en neer tegen de achterkant van de koe op de plaats waar zich een sensorische zenuw bevindt. Dit veroorzaakt een reflex die ervoor zorgt dat de koe gaat plassen. De urine komt in de opvangbak terecht en wordt afgevoerd.
afbeelding 1: tekening van een koe met een opvangbak tegen de achterkant$$, 'inline'),
  ('40bbcb5d-5462-419e-9e6e-19b7e33c3785', '6c36657f-fe28-464f-a17f-37f3d41de11f', $$drie uitspraken over de plasreflex$$,
   $$biologie-havo-2025-ii-koeientoilet-context5.png$$,
   $$Hieronder staan uitspraken over de plasreflex.
1 Deze reflex verloopt via de hersenstam.
2 De kern van de betrokken motorische zenuwcel ligt in het ruggenmerg.
3 De betrokken motorische zenuwcel activeert tijdens de reflex de sluitspier van de blaas.$$, 'inline'),
  ('94f7da55-50d9-4c2d-8386-4b1290f67d9f', '6c36657f-fe28-464f-a17f-37f3d41de11f', $$kader: kleine zonnedauw, een vleesetende plant (afbeelding 2)$$,
   $$biologie-havo-2025-ii-koeientoilet-context6.png$$,
   $$Het valt Andrea op dat er de afgelopen jaren in het Korenburgerveen steeds minder kleine zonnedauw te zien is. Mogelijk heeft de kleine zonnedauw in het gebied last van de stikstofuitstoot van het bedrijf van Andrea. Kleine zonnedauw (Drosera intermedia, afbeelding 2) is een plantje dat maximaal 10 cm hoog wordt.
afbeelding 2: foto van zonnedauw
Zonnedauw is een groep van vleesetende planten met groene bladeren en bladeren met kleverige druppels. Hieraan blijven insecten plakken. De bladeren scheiden enzymen af, waardoor de insecten worden verteerd. Bij de vertering ontstaan stikstofverbindingen die de plant opneemt voor de groei.$$, 'inline'),
  ('6178ad48-dec8-4f08-8c3b-06ccfd3de2c9', '6c36657f-fe28-464f-a17f-37f3d41de11f', $$zonnedauw is een producent$$,
   $$biologie-havo-2025-ii-koeientoilet-context7.png$$,
   $$Zonnedauw behoort tot de producenten en niet tot de consumenten.$$, 'inline'),
  ('593ea699-b406-4972-9a63-3b05df781c2e', '6c36657f-fe28-464f-a17f-37f3d41de11f', $$kader: Zweeds onderzoek met ronde zonnedauw en stikstof$$,
   $$biologie-havo-2025-ii-koeientoilet-context8.png$$,
   $$Onderzoekers in Zweden deden onderzoek naar de invloed van stikstofverbindingen in de bodem op de aanwezigheid van zonnedauw. Zij hebben een veld waar ronde zonnedauw (Drosera rotundifolia) groeit, opgedeeld in vijf delen. Aan deze delen dienden ze jaarlijks verschillende hoeveelheden van een anorganische stikstofverbinding toe. De onderzoekers hebben er vier jaar lang in september en in juni het aantal plantjes zonnedauw per vierkante meter geteld.$$, 'inline'),
  ('26665b26-b748-4afa-a776-828d96f512d8', '6c36657f-fe28-464f-a17f-37f3d41de11f', $$afbeelding 3: aantal zonnedauwplantjes bij vijf stikstofhoeveelheden$$,
   $$biologie-havo-2025-ii-koeientoilet-context9.png$$,
   $$De resultaten van het onderzoek staan in afbeelding 3.
afbeelding 3: lijndiagram aantal individuen (per m²) van sep jaar 1 tot sep jaar 4 bij 0,0 / 0,5 / 1,0 / 2,0 / 4,0 gram N / m² / jaar; bij 0,0, 0,5 en 1,0 gram blijft het aantal tussen ongeveer 300 en 600; bij 2,0 en 4,0 gram daalt het aantal van ongeveer 300-440 naar ongeveer 50-70$$, 'inline'),
  ('a013dcc2-4c7b-415f-ba1c-781e2c4668b0', '6c36657f-fe28-464f-a17f-37f3d41de11f', $$drie conclusies over het Zweedse onderzoek$$,
   $$biologie-havo-2025-ii-koeientoilet-context10.png$$,
   $$Hieronder staan drie conclusies.
1 1,0 gram N / m² / jaar is de optimum-waarde voor stikstofbemesting van ronde zonnedauw.
2 Er is geen verband tussen de toegediende hoeveelheid stikstof en het aantal plantjes van ronde zonnedauw.
3 De afname van kleine zonnedauw in het Korenburgerveen wordt veroorzaakt door een verhoogde stikstofuitstoot.$$, 'inline'),
  ('f5e84062-56f7-4e8e-ac81-771db6c38344', '6c36657f-fe28-464f-a17f-37f3d41de11f', $$kader: veenpluis verdringt kleine zonnedauw (afbeelding 4)$$,
   $$biologie-havo-2025-ii-koeientoilet-context11.png$$,
   $$In veel natuurgebieden in Nederland staat op plaatsen waar eerst voornamelijk kleine zonnedauw groeide, nu vooral veenpluis. Dit is het gevolg van de hogere stikstofconcentraties in die gebieden. Veenpluis (Eriophorum angustifolium, afbeelding 4) is een grassoort die maximaal 60 cm hoog wordt.
afbeelding 4: foto van veenpluis$$, 'inline'),
  ('f413a081-d78d-443a-83eb-c5f76ab7e3df', '6c36657f-fe28-464f-a17f-37f3d41de11f', $$stikstofconcentraties binnen de tolerantiegrenzen$$,
   $$biologie-havo-2025-ii-koeientoilet-context12.png$$,
   $$De hogere stikstofconcentraties liggen wel binnen de tolerantiegrenzen van kleine zonnedauw.$$, 'inline'),
  ('93fbd7a7-a582-492e-8b9c-0a843b6f9eb4', 'eec1cdfb-a5ab-4a80-b5c1-57a63e450b47', $$inleiding: driehoornkameleons op Oahu$$,
   $$biologie-havo-2025-ii-kameleon-bekent-kleur-context1.png$$,
   $$In 1972 kwam er op Oahu, een eiland van Hawaï, een vracht aan met 36 driehoornkameleons uit Kenia. De dieren ontsnapten en nu komt de soort algemeen voor op het eiland Oahu.$$, 'inline'),
  ('b2beb9ac-fd01-464b-b284-76279ccb96ef', 'eec1cdfb-a5ab-4a80-b5c1-57a63e450b47', $$kader: felle kleuren als signaal$$,
   $$biologie-havo-2025-ii-kameleon-bekent-kleur-context2.png$$,
   $$Driehoornkameleons gebruiken hun felle kleuren om signalen te geven aan hun soortgenoten. De driehoornkameleons die op Oahu leven, zijn kleurrijker dan de driehoornkameleons die in Kenia leven. Tot 1972 leefden er geen driehoornkameleons op Oahu.
foto van een driehoornkameleon$$, 'inline'),
  ('49f24e43-9f89-499b-9c81-038b8d20e818', 'eec1cdfb-a5ab-4a80-b5c1-57a63e450b47', $$afwezigheid van predatoren en andere factoren$$,
   $$biologie-havo-2025-ii-kameleon-bekent-kleur-context3.png$$,
   $$Een verklaring voor de vestiging en snelle verspreiding van de driehoornkameleons op Oahu, is de afwezigheid van predatoren. Er zullen echter ook andere factoren een rol gespeeld hebben.$$, 'inline'),
  ('7b11767e-8519-4043-87e7-675c5aafcb3c', 'eec1cdfb-a5ab-4a80-b5c1-57a63e450b47', $$geografische scheiding maar dezelfde soort$$,
   $$biologie-havo-2025-ii-kameleon-bekent-kleur-context4.png$$,
   $$De driehoornkameleons uit Oahu en Kenia zijn geografisch gescheiden. Toch is het waarschijnlijk dat zij nog steeds samen vruchtbare nakomelingen kunnen krijgen, en daarmee tot dezelfde soort behoren.$$, 'inline'),
  ('09a0bac1-083c-4186-a19a-43c9898bf8af', 'eec1cdfb-a5ab-4a80-b5c1-57a63e450b47', $$genetische kleurverschillen; drie uitspraken$$,
   $$biologie-havo-2025-ii-kameleon-bekent-kleur-context5.png$$,
   $$De verschillen in kleur tussen de driehoornkameleons op Oahu en in Kenia worden veroorzaakt door genetische verschillen. Hieronder staan uitspraken die een mogelijke verklaring geven voor de genetische verschillen.
1 De 36 dieren die in 1972 ontsnapten, waren in Kenia geselecteerd op hun fellere kleuren.
2 Het voedsel op Oahu bevat meer natuurlijke kleurstoffen.
3 In Kenia hebben de felgekleurde driehoornkameleons een lagere fitness door de aanwezigheid van predatoren.$$, 'inline'),
  ('7b8698f4-7d9a-4c96-a8c0-02ced5590367', 'eec1cdfb-a5ab-4a80-b5c1-57a63e450b47', $$kader: kleurverandering door stervormige pigmentcellen$$,
   $$biologie-havo-2025-ii-kameleon-bekent-kleur-context6.png$$,
   $$De kleur van kameleons wordt bepaald door de rangschikking van verschillende moleculen in de cellen van de huid en door stervormige cellen met zwart pigment. Het pigment in de stervormige cellen kan verspreid of geconcentreerd worden, waardoor de huid donkerder of lichter wordt. Hiermee reguleert de kameleon, die koudbloedig is, zijn lichaamstemperatuur. In de ochtend zijn kameleons donkerder van kleur, waardoor ze sneller opwarmen.
tekening: stervormige cel bij donkere huid (pigment verspreid in de cel) en bij lichte huid (pigment geconcentreerd in het midden)$$, 'inline'),
  ('2e7b4055-436a-4207-bba5-fe5e64ac8dd8', 'eec1cdfb-a5ab-4a80-b5c1-57a63e450b47', $$aansturing door het zenuwstelsel of door hormonen$$,
   $$biologie-havo-2025-ii-kameleon-bekent-kleur-context7.png$$,
   $$De verspreiding van het pigment in de stervormige cellen wordt aangestuurd door het zenuwstelsel. Bij andere diersoorten die van kleur kunnen veranderen, worden kleurveranderingen meestal veroorzaakt door hormonen.$$, 'inline'),
  ('6d0b3ccf-67e4-4f88-9b2b-eec6f2d994f6', 'eec1cdfb-a5ab-4a80-b5c1-57a63e450b47', $$stamboom van kameleongeslachten en drie uitspraken$$,
   $$biologie-havo-2025-ii-kameleon-bekent-kleur-context8.png$$,
   $$Er zijn zo’n 200 soorten kameleons bekend. Deze zijn onderverdeeld in verschillende geslachten (genera). In de stamboom is een aantal van deze geslachten te zien, waaronder ook het geslacht Trioceros waartoe de driehoornkameleon behoort.
stamboom van de geslachten Brookesia, Archalus, Rhampholeon, Kinyongia, Trioceros, Furcifer, Calumma en Bradypodion met een tijdas van 60 tot 0 miljoen jaar geleden
Hieronder staan uitspraken over deze stamboom.
1 Het geslacht Brookesia is de voorouder van alle andere geslachten.
2 De laatste gemeenschappelijke voorouder van het geslacht Trioceros en het geslacht Kinyongia leefde in de geologische periode Jura.
3 Het geslacht Rhampholeon is meer verwant met het geslacht Kinyongia dan met het geslacht Trioceros.$$, 'inline'),
  ('b8b741db-3d9f-4bf3-87b7-40db96bd2feb', '736e80df-b46f-41dd-af78-c75cef75856b', $$inleiding: kat Rio heeft chronisch nierfalen$$,
   $$biologie-havo-2025-ii-nierfalen-bij-katten-context1.png$$,
   $$Met Maureens kat Rio gaat het niet zo goed. Rio is erg vermagerd. De dierenarts heeft de urine en het bloed van Rio laten onderzoeken. Daaruit bleek dat ze aan chronisch nierfalen lijdt.$$, 'inline'),
  ('8859bb98-abd5-44f3-996b-f05ab51dbd41', '736e80df-b46f-41dd-af78-c75cef75856b', $$kader: afvalstoffen hopen zich op in het bloed$$,
   $$biologie-havo-2025-ii-nierfalen-bij-katten-context2.png$$,
   $$Bij chronisch nierfalen is de nierfunctie sterk verminderd, waardoor afvalstoffen zich ophopen in het bloed. Katten met chronisch nierfalen drinken daardoor veel.$$, 'inline'),
  ('28111e8b-76a1-4f8d-bd90-4973c04b3ca1', '736e80df-b46f-41dd-af78-c75cef75856b', $$vier processen in het lichaam van een kat$$,
   $$biologie-havo-2025-ii-nierfalen-bij-katten-context3.png$$,
   $$Hieronder staan processen in het lichaam van een kat.
1 De osmotische waarde van het bloed daalt.
2 De osmotische waarde van het bloed stijgt.
3 Het dorstcentrum zorgt dat de kat gaat drinken.
4 Osmoreceptoren geven signalen door.$$, 'inline'),
  ('dd8e8eb3-c153-494e-9c87-64dfffbd9b8f', '736e80df-b46f-41dd-af78-c75cef75856b', $$dichtheid van de urine$$,
   $$biologie-havo-2025-ii-nierfalen-bij-katten-context4.png$$,
   $$De dierenarts bepaalt bij het urine-onderzoek de dichtheid van de urine. De dichtheid van water is ongeveer 1000 gram / L. Een zoutoplossing heeft een hogere dichtheid. Als de dichtheid van de urine van katten lager is dan 1035 gram / L, zijn er mogelijk nierproblemen. De urine van Rio blijkt een dichtheid van 1005 gram / L te hebben.$$, 'inline'),
  ('d781d193-57c1-4425-9237-84fb05250381', '736e80df-b46f-41dd-af78-c75cef75856b', $$ureum uit de lever; acht bloedvaten$$,
   $$biologie-havo-2025-ii-nierfalen-bij-katten-context5.png$$,
   $$In het bloed van Rio wordt een te hoog ureum-gehalte gemeten. Ureum wordt in de lever aangemaakt. Hieronder staan enkele bloedvaten.
1 aorta
2 bovenste holle ader
3 leverader
4 leverslagader
5 longader
6 longslagader
7 onderste holle ader
8 poortader$$, 'inline'),
  ('7c21472c-7634-4086-9210-7a6e2c2a2649', '736e80df-b46f-41dd-af78-c75cef75856b', $$kader: glomerulus en kapsel van Bowman (afbeelding 1 en 2)$$,
   $$biologie-havo-2025-ii-nierfalen-bij-katten-context6.png$$,
   $$Bij een kat met chronisch nierfalen zijn afwijkingen te zien in een microscopisch preparaat van het nierweefsel. De glomerulus is vergroot, en de ruimte in het kapsel van Bowman is deels gevuld met bindweefsel. Afbeelding 1 is een schematische tekening van het kapsel van Bowman met de glomerulus.
afbeelding 1: tekening van het kapsel van Bowman met de glomerulus en het begin van het nierbuisje, met twee horizontale stippellijnen voor doorsnedeplaats 1 (hoger) en 2 (lager)
Afbeelding 2 is een foto van een microscopisch preparaat van nierweefsel van een kat met chronisch nierfalen.
afbeelding 2: microscopische foto met bindweefsel en de letters P en Q$$, 'inline'),
  ('7446619c-a2e4-4414-8648-f9c7a5f31e21', '736e80df-b46f-41dd-af78-c75cef75856b', $$eiwitrijke voeding en ureumvorming; twee ontbrekende woorden$$,
   $$biologie-havo-2025-ii-nierfalen-bij-katten-context7.png$$,
   $$Maureen geeft Rio voeding met een aangepaste eiwitsamenstelling. Het eten van te veel eiwitten zou namelijk leiden tot de productie van veel ureum, wat schadelijk is voor Rio. Hieronder staat hoe de grote hoeveelheid ureum ontstaat. Op twee plaatsen ontbreekt een woord.
Bij de vertering van de grote hoeveelheid eiwitten worden veel ...(1)... gevormd, die daarna worden geresorbeerd in de darm. Een groot gedeelte hiervan wordt vervolgens afgebroken door de ...(2)... van Rio. Bij deze afbraak ontstaat ureum.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('a5bf4f39-d948-4b15-8ce4-b6c018f14db2', '938ef4f5-eca1-4dae-8041-bbe5bbde4b1f', 1,
   '[{"domain": "Zelfregulatie", "subdomain": "Stofwisseling van het organisme"}]'::jsonb,
   '["hartbouw", "rechterkamer", "hartwand", "aangeboren hartafwijking", "afbeelding interpreteren"]'::jsonb,
   $$Herkennen van een verdikte wand van de rechterkamer als vierde afwijking van het hart.$$,
   $$biologie-havo-2025-ii-de-tetralogie-van-fallot-vraag1.png$$, $$1p 1 Noteer dit vierde verschil.$$, array['05c37b33-9b4d-4611-8330-e111a5c04353', '0a2cff04-9ea2-4246-a632-1361d6bc3f06', 'a68cb578-30e3-4611-a3aa-1e3a921c156c']::uuid[]),
  ('25ce104a-b6f4-421c-8001-d89e479cf62f', '938ef4f5-eca1-4dae-8041-bbe5bbde4b1f', 2,
   '[{"domain": "Zelfregulatie", "subdomain": "Stofwisseling van het organisme"}]'::jsonb,
   '["diastole", "systole", "hartklep", "longslagader", "hartcyclus"]'::jsonb,
